// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: owner() should always return the originally initialized owner, not the caller.
    // We fuzz an arbitrary caller address to call owner() and assert owner() != caller in the general case
    // for the reference contract. The mutant that returns msg.sender will make owner() == caller for
    // some fuzzed callers, causing the test to fail.
    function testFuzz_property(address caller) public {
        // keep domain wide but non-zero to avoid the trivial zero-address interactions
        vm.assume(caller != address(0));

        // Initialize contract as a specific owner (the test contract)
        // __Ownable_init is called inside initialize; pass some initialization data
        vm.prank(address(this));
        c.initialize({credChainId_: 1, credId_: 2, verificationType_: "v", protocolFeeDestination_: address(this)});

        // Call owner() as the fuzzed caller
        address observedOwner;
        vm.prank(caller);
        observedOwner = c.owner();

        // The reference contract always returns the stored owner (address(this)), which is independent of caller.
        // So for ALL callers, observedOwner == address(this). The mutant will return caller for some inputs,
        // making this assertion fail for those inputs.
        assertTrue(observedOwner == address(this));
    }
}

