pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: an address caller that the fuzzer will vary
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be different from zero and different from deployer (the initializer)
        vm.assume(caller != address(0));
        // initialize the contract as deployer (this test contract) to set stored owner = address(this)
        c.initialize({credChainId_: 1, credId_: 2, verificationType_: "v", protocolFeeDestination_: address(this)});

        // ensure stored owner is address(this)
        address storedOwner = c.owner();
        // sanity: storedOwner should equal this contract
        // But we must allow fuzzed caller possibly equal to this; we keep admissible domain wide but not exclude equality

        // Call owner() as the fuzzed caller using a try/catch to capture potential weird reverts (should not revert)
        bool ok;
        address reportedOwnerByCaller;
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            reportedOwnerByCaller = o;
        } catch {
            ok = false;
            reportedOwnerByCaller = address(0);
        }

        // The universal property: reference returns the stored owner regardless of caller, so the call must succeed
        // and reportedOwnerByCaller must equal storedOwner. The mutant that returns msg.sender will cause a mismatch
        // whenever caller != storedOwner.
        assertTrue(ok && reportedOwnerByCaller == storedOwner);
    }
}

