    C c;
    address deployer = address(0xABCD);

    function setUp() public {
        vm.prank(deployer);
        c = new C();

        // initialize as the deployer (phiFactoryContract expected to be msg.sender in initialize)
        vm.prank(deployer);
        c.initialize(1, 2, "vtype", address(0xBEEF));
    }

    // fuzz the caller address to detect if owner() depends on msg.sender
    function testFuzz_property(address caller) public {
        // admissible domain: caller can be any address
        // ensure caller is not the stored owner to allow distinguishing behavior
        vm.assume(caller != deployer);

        // call owner() as the fuzzed caller and observe whether it equals the stored owner (deployer)
        bool ok;
        try c.owner() returns (address o) {
            // When invoked normally (from this test contract's context), owner() returns an address.
            // But to simulate caller, use vm.prank to make the call from 'caller' and read the return via a view call.
            vm.prank(caller);
            address res = c.owner();
            // The universal property: reference contract always returns stored owner (deployer).
            ok = (res == deployer);
        } catch {
            // if it reverts, treat as not ok
            ok = false;
        }

        // This single assertion should hold for the correct contract for all callers, but fail for mutant when caller != deployer
        assertTrue(ok);
