pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed boolean param will determine whether owner pauses or unpauses the contract
    function testFuzz_property(bool doPause) public {
        // general rule: paused() should reflect the internal _paused state; we exercise both states
        address owner = address(this);
        // initialize contract (C is Initializable and expects initialize called by factory msg.sender in real usage)
        // but C.initialize uses msg.sender as owner; call it from this contract
        c.initialize({
            credChainId_: 1,
            credId_: 1,
            verificationType_: "v",
            protocolFeeDestination_: owner
        });

        // Ensure starting state: contract is not paused immediately after __Pausable_init which sets _paused = false
        bool before = c.paused();
        // Now fuzz: if doPause true, call pause() as owner to set paused state; otherwise leave as-is
        if (doPause) {
            c.pause();
        } else {
            // ensure unpaused state by calling unPause in case pause was previously called — safe to call when not paused
            // but unPause requires onlyOwner; owner is this, so it's fine
            c.unPause();
        }

        // Observe paused after our action
        bool after = c.paused();

        // The universal property: after equals the internal stored _paused; specifically, when we called pause() it must be true,
        // and when we left unpaused it must be false. We assert that paused() equals doPause OR (if doPause==false) equals false.
        // Equivalent single assertion: paused() == doPause
        // This holds on the reference implementation for all inputs; the mutant inverts the returned value and will fail for some input.
        assertTrue(after == doPause);
    }
}

