pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the boolean that decides whether we call pause() or unPause() (as an uint8)
    function testFuzz_property(uint8 flip) public {
        // keep domain wide: interpret even/odd from flip
        bool doPause = (flip % 2 == 0);

        // At initialization, C is deployed but not initialized via initialize(), so PausableStorage was set to false by __Pausable_init_unchained in initialize; however constructor called _disableInitializers(), so we must emulate the typical lifecycle by calling initialize to set paused to false explicitly.
        // initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_)
        // The initialize function is external and sets owner to msg.sender, so call it from this contract
        c.initialize(1, 2, "vt", address(this));

        // ensure starting paused() is false
        bool before = c.paused();

        // perform action chosen by fuzz input
        if (doPause) {
            // pause requires onlyOwner; this contract is owner after initialize
            c.pause();
        } else {
            // unPause also requires onlyOwner; calling when already unpaused may revert if already unpaused, so guard by checking paused()
            if (c.paused()) {
                c.unPause();
            } else {
                // if not paused, calling unPause would revert (require whenPaused) so skip
            }
        }

        // read observed paused state after operation
        bool observed = c.paused();

        // General rule: the getter paused() should equal the internal stored paused boolean; in the reference contract, toggling via pause()/unPause() flips paused() accordingly.
        // We assert a relation that must hold for the reference but will fail on the mutant for some inputs: if we didPause then observed must be true; if we did not doPause then observed must be false (unless we performed an unPause when already unpaused, which we avoided).
        if (doPause) {
            assertTrue(observed);
        } else {
            assertTrue(!observed);
        }
    }
}

