    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: a boolean deciding whether we perform a pause() or unPause()
    function testFuzz_property(bool doPause) public {
        // Keep domain wide: bool is already simple; no assume needed.

        // Ensure caller is owner (deployer) since setUp set deployer as this test contract
        // In initialize the owner is msg.sender, but constructor _disableInitializers was called.
        // We will initialize c by calling initialize as the phiFactory (owner in initialize is msg.sender).
        // The contract's initialize requires msg.sender to be a phiFactory; but it just sets owner to msg.sender.
        // Here we call initialize from this test contract so owner will be this test contract.

        // Provide minimal admissible params to initialize
        uint256 credChainId_ = 1;
        uint256 credId_ = 2;
        string memory verificationType_ = "v";
        address protocolFeeDestination_ = address(this);

        // initialize (this makes this test contract the owner)
        c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_);

        // Now ensure contract starts unpaused; default _paused is false, so paused() should be false.
        // Depending on fuzzed doPause, call pause() or unPause() to set stored _paused to true/false.
        if (doPause) {
            c.pause();
        } else {
            // ensure unpaused: if currently paused call unPause, else no-op
            // calling unPause when not owner would revert, but this contract is owner
            // unPause reverts if not paused; call only when paused to avoid revert
            // So check current stored paused via c.paused() and call unPause only if needed
            if (c.paused()) {
                c.unPause();
            }
        }

        // Now read the public paused() view. The correct contract returns the stored flag.
        // The mutant inverts it. We assert that paused() equals the stored logical state we expect.
        // Expected stored state is doPause ? true : false.
        bool expected = doPause;

        // Exactly one assertion as required
        assertTrue(c.paused() == expected);
    }
}

