import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: a boolean that we will use to decide whether to call pause or unPause
    function testFuzz_property(bool doPause) public {
        // admissible domain: none to restrict, both choices valid

        // ensure owner context (setUp used new C(); its owner is the deployer, which is address(this))
        // if doPause is true, pause the contract; otherwise ensure it's unpaused
        if (doPause) {
            // onlyOwner can pause; we are the owner
            c.pause();
        } else {
            // ensure unpaused state: unPause may only be called when paused; so if currently paused, unpause
            // but on fresh instance it's unpaused by default, so calling unPause only when paused
            // we'll attempt to pause and then unpause to guarantee unpaused state when doPause == false
            // Only perform if currently paused to avoid revert: use try/catch on pause()
            // Actually pause() will not revert when called by owner; calling pause then unPause ensures unpaused
            // Do a safe sequence: if contract is paused, unpause; else leave
            // But we cannot read internal storage directly. Use c.paused() to check current visible value.
            // c.paused() is a view that should reflect stored state in reference; even if mutant flips it,
            // we only need to achieve the stored state matching doPause in the reference. We'll simply
            // perform pause then unpause to end unpaused state deterministically.
            c.pause();
            c.unPause();
        }

        // Now read the paused() getter
        bool reported;
        try c.paused() returns (bool v) {
            reported = v;
        } catch {
            // paused() should not revert in either reference or mutant; treat revert as false (but this will fail assertion if unexpected)
            reported = false;
        }

        // The single universal assertion: in the reference implementation, after performing the above sequence,
        // the stored paused state equals doPause, therefore paused() should return doPause for all inputs.
        // The mutant flips the returned value, so for some fuzz input (both true/false) it will fail.
        assertTrue(reported == doPause);
    }
}

