pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the desired stored paused state by driving the contract with pause/unPause calls
    function testFuzz_property(bool callPauseFirst) public {
        // admissible domain: no extra restrictions needed
        // Drive the contract into one of the two stored paused states using the public pause/unPause functions
        // Only owner can call pause/unPause; set msg.sender as owner (deployer) by default

        if (callPauseFirst) {
            c.pause();
        } else {
            // ensure unpaused: calling unPause when already unpaused is allowed for owner
            // contract initializes unpaused by default; still call unPause to exercise both branches
            c.unPause();
        }

        // Now read the paused() getter via a try/catch to capture any unexpected revert (shouldn't revert)
        bool ok;
        bool returned;
        try c.paused() returns (bool r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = false;
        }

        // The property: the paused() call MUST NOT revert (ok == true) and its return MUST equal the actual stored state
        // We derive the actual stored state by calling the public paused() again — but to ensure a single assertion,
        // we compute the expected stored state from the sequence we executed: if we called pause(), expected is true; else false.
        bool expected = callPauseFirst ? true : false;

        // exactly one assertion as required: the reference implementation yields paused() == expected for all inputs,
        // while the mutant (which returns the negation) will differ for some input (fuzzer will find it).
        assertTrue(ok && returned == expected);
    }
}

