    C c;

    function setUp() public { c = new C(); }

    // fuzz a tokenId and an address to act as protocolFeeDestination (also used as royalty recipient)
    function testFuzz_property(uint256 tokenId, address royaltyRecipient) public {
        // keep inputs wide but avoid zero address for initial owner/recipient where necessary
        vm.assume(royaltyRecipient != address(0));

        // initialize the contract as the deployer (setUp used new C(), deployer is address(this))
        // The initialize function expects (credChainId_, credId_, verificationType_, protocolFeeDestination_)
        c.initialize({credChainId_: block.chainid, credId_: 42, verificationType_: "v", protocolFeeDestination_: royaltyRecipient});

