import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz tokenId and an arbitrary nonzero address to use as initializer's caller (prank sender)
    function testFuzz_property(uint256 tokenId, address initializer) public {
        // ensure initializer is non-zero (initialize requires non-zero royalty recipient)
        vm.assume(initializer != address(0));

        // call initialize as the phi factory (constructor expects msg.sender to be phiFactory)
        // The contract's initialize uses msg.sender as the phiFactory and also passes msg.sender to initializeRoyalties
        // which requires a non-zero _royaltyRecipient. So we prank initializer to be msg.sender.
        vm.prank(initializer);
        c.initialize(1, 2, "v", initializer);

        // After initialization, for any tokenId that has no per-token config (default mapping value),
        // getRoyalties should return the global royaltyRecipient and royaltyBPS == 500 in the reference.
        // We fuzz tokenId so the fuzzer will search for values; the mutant returns royaltyBPS == 1000 instead.

        // Query royalties via public getter
        C.RoyaltyConfiguration memory rc = c.getRoyalties(tokenId);

        // Exactly one assertion: royaltyRecipient equals initializer (the global recipient) AND royaltyBPS == 500.
        // This holds for the reference for all tokenId where no per-token recipient is set (which is all tokenIds initially),
        // and fails on the mutant for those tokenIds because royaltyBPS would be 1000.
        assertTrue(rc.royaltyRecipient == initializer && rc.royaltyBPS == 500);
